def _block_ok_cache(self):
    """Return a ``(bid, sink) -> bool`` block verifier with a cache.

    The cache remembers which content-addressed blocks have already
    streamed clean in this operation, so a block shared by several
    manifests is fully read at most once even though each manifest
    composes its own snapshot hash: a cached-good block still feeds a
    first-time caller's ``sink`` from the manifest's own blocks when
    needed -- callers that only need a validity answer (``sink is
    None``) never force a re-read.
    """
    good: dict = {}

    def ok(bid: bytes, sink=None) -> bool:
        path = self._block_path(bid)
        if bid in good:
            if sink is None:
                return True
            # The caller needs the bytes in its own hash; verify_manifest
            # paths needing composition run their own single read below.
            return False if not _verify_named_block(path, bid, sink) else True
        verdict = _verify_named_block(path, bid, sink)
        good[bid] = verdict
        return verdict

    return ok

