# Global block pass. Every manifest record gets one composition
# hash; each distinct referenced block is streamed exactly once and
# its frame bytes are fed into every manifest hash naming it in that
# same single read, while the block's own content identity is
# checked. Every manifest lists blocks in the same canonical key
# order, so the per-manifest predecessor chains are mutually
# consistent: a deterministic topological merge gives one reading
# order in which each waiter's hash receives its blocks in exactly
# its own ref order, with no block read twice. A missing or
# self-inconsistent block fails every manifest naming it.
for rec in raw:
    if rec[2] == "m":
        rec.append(hashlib.sha256())
users: dict = {}
preds: dict = {}
for rec in raw:
    if rec[2] != "m":
        continue
    prev = None
    for bid in rec[4]:
        users.setdefault(bid, []).append(rec)
        preds.setdefault(bid, set())
        if prev is not None:
            preds[bid].add(prev)
        prev = bid
order = []
remaining = dict(preds)
while remaining:
    ready = sorted((bid for bid, need in remaining.items()
                    if not need), key=bytes)
    if not ready:
        # Two chains disagree about block order, which cannot happen
        # for canonical (key-sorted) manifests: treat it as damage.
        return [], [], [rec[3] for rec in raw if rec[2] == "m"]
    for bid in ready:
        order.append(bid)
        del remaining[bid]
    done = set(ready)
    for need in remaining.values():
        need -= done
block_good: dict = {}
for bid in order:
    recs = users[bid]
    digests = [rec[5] for rec in recs]

    def feed(data, digests=digests):
        for dg in digests:
            dg.update(data)

    ok = False
    try:
        with open(self._block_path(bid), "rb") as f:
            result = _stream_one_frame(
                f, self._twin_sink(bid, digests))
            if result is not None and result is not False:
                meta, _v, _l = result
                if (isinstance(meta, dict) and meta.get("t") == _OP_PUT
                        and isinstance(meta.get("k"), str)
                        and meta.get("k") != ""
                        and not f.read(1)):
                    ok = self._last_block_own == bid
    except OSError:
        ok = False
    block_good[bid] = ok

